        <tr><td>Java</td><td>79.9</td><td>Medium</td><td>Stable enterprise demand</td></tr>
        <tr><td>Excel</td><td>79.8</td><td>High</td><td>Declining differentiation; automate-able</td></tr>
        <tr><td>Deep Learning</td><td>79.6</td><td>Low</td><td>Strong — core AI capability</td></tr>
        <tr><td>Strategy</td><td>79.6</td><td>Medium</td><td>Human judgment dependent</td></tr>
