        <tr><td>ML Engineer</td><td>~1.8</td><td><span class="tag tag-low">Strong</span></td><td>Invest & expand</td></tr>
        <tr><td>DevOps Engineer</td><td>~1.5</td><td><span class="tag tag-medium">Moderate</span></td><td>Upskill toward platform engineering</td></tr>
        <tr><td>Data Scientist</td><td>~1.4</td><td><span class="tag tag-medium">Moderate</span></td><td>Shift toward research & architecture</td></tr>
        <tr><td>Cloud Engineer</td><td>~1.4</td><td><span class="tag tag-medium">Moderate</span></td><td>Add AI/ML infrastructure skills</td></tr>
